nextflow_process {

    name "Test Process FQ_GENERATE"
    script "../main.nf"
    process "FQ_GENERATE"

    tag "modules"
    tag "modules_nfcore"
    tag "fq"
    tag "fq/generate"

    test("test fq") {
        config "./nextflow.config"
        when {
            process {
                """
                input[0] = Channel.of( [ id:'test', single_end:false ] )
                """
            }
        }

        then {
            assertAll (
                { assert process.success },
                { assert snapshot(process.out).match() },
            )
        }

    }

    test("test fq -stub") {
        options "-stub"
        when {
            process {
                """
                input[0] = Channel.of( [ id:'test', single_end:false ] )
                """
            }
        }

        then {
            assertAll (
                { assert process.success },
                { assert snapshot(process.out).match() },
            )
        }

    }

}

